class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        adjacency = [[] for _ in range(n)]
        for u, v, length in edges:
            adjacency[u].append((v, length))
            adjacency[v].append((u, length))

        self.longest_length = 0
        self.min_nodes = n

        def dfs(node: int, parent: int, current_length: int, values: set):
            # Update the global result
            if current_length > self.longest_length:
                self.longest_length = current_length
                self.min_nodes = len(values)
            elif current_length == self.longest_length:
                self.min_nodes = min(self.min_nodes, len(values))
            for neighbor, length in adjacency[node]:
                if neighbor != parent and nums[neighbor] not in values:
                    values.add(nums[neighbor])
                    dfs(neighbor, node, current_length + length, values)
                    values.remove(nums[neighbor])

        # Start DFS from each node as the root of the path
        for start in range(n):
            values = set()
            values.add(nums[start])
            dfs(start, -1, 0, values)

        return [self.longest_length, self.min_nodes]

