                    for j in range(n):
                        increments = ((nums[j] + target[i] - 1) // target[i]) * target[i] - nums[j]
                        new_mask = mask | (1 << i)
                        dp[new_mask] = min(dp[new_mask], dp[mask] + increments)

        return dp[(1 << m) - 1]

