class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        # Prefix sums
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        # DP: dp[i][j] = max sum using first i elements and j subarrays
        # Initialize DP with -inf
        dp = [[float('-inf')] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 0  # Base case: 0 elements, 0 subarrays, sum = 0

        for i in range(1, n + 1):
            for j in range(0, k + 1):
                # Option 1: don't take a subarray ending at i
                dp[i][j] = dp[i - 1][j]
                # Option 2: take a subarray of length l ending at i
                if j > 0:
                    for l in range(m, min(i, m) + 1):
                        if dp[i - l][j - 1] != float('-inf'):
                            dp[i][j] = max(dp[i][j], dp[i - l][j - 1] + prefix[i] - prefix[i - l])

        return dp[n][k]

