    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Create a copy of the grid to avoid modifying the input directly
        result = [row[:] for row in grid]

        # Iterate over all possible diagonals
        for d in range(-(n - 1), n):
            # Collect the elements of the current diagonal
            diagonal = []
            for i in range(n):
                j = i - d
                if 0 <= j < n:
                    diagonal.append(grid[i][j])

            # Sort the diagonal accordingly
            if d <= 0:
                # Bottom-left triangle (including the main diagonal): sort in non-increasing order
                diagonal.sort(reverse=True)
            else:
                # Top-right triangle: sort in non-decreasing order
                diagonal.sort()

            # Put the sorted elements back into the result grid
            idx = 0
            for i in range(n):
                j = i - d
                if 0 <= j < n:
                    result[i][j] = diagonal[idx]
                    idx += 1

        return result

