    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        dp = {(0, 0): 1}  # (alternating sum, parity) -> max product
        for num in nums:
            dp2 = dp.copy()
            for (s, p), prod in dp.items():
                s2 = s + num if p == 0 else s - num
                prod2 = prod * num
                if prod2 <= limit:
                    dp2[(s2, 1 - p)] = max(dp2.get((s2, 1 - p), 0), prod2)
            dp = dp2
        max_product = -1
        for (s, p), prod in dp.items():
            if s == k:
                max_product = max(max_product, prod)
        return max_product

