    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Sort the points for consistency
        points.sort()
        n = len(points)

        # Function to check if we can select k points with at least distance d
        def can_select(d: int) -> bool:
            # Backtracking with pruning
            selected = []

            def backtrack(start: int) -> bool:
                if len(selected) == k:
                    return True
                if start >= n:
                    return False
                # Prune if not enough points left
                if n - start < k - len(selected):
                    return False
                for i in range(start, n):
                    # Check if this point is at least distance d from all selected points
                    ok = True
                    for x, y in selected:
                        if abs(x - points[i][0]) + abs(y - points[i][1]) < d:
                            ok = False
                            break
                    if ok:
                        selected.append(points[i])
                        if backtrack(i + 1):
                            return True
                        selected.pop()
                return False

            return backtrack(0)

        # Binary search on the distance
        low, high = 0, 2 * side
        while low < high:
            mid = (low + high + 1) // 2
            if can_select(mid):
                low = mid
            else:
                high = mid - 1
        return low

