class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # dp[i][j] = minimum number of operations to make s[i:j+1] a palindrome
        dp = [[0] * n for _ in range(n)]
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if s[i] == s[j]:
                    dp[i][j] = dp[i + 1][j - 1]
                else:
                    dp[i][j] = 1 + min(dp[i + 1][j], dp[i][j - 1])
        # Find the longest palindrome length with at most k operations
        max_len = 0
        for i in range(n):
            for j in range(i, n):
                if dp[i][j] <= k:
                    max_len = max(max_len, j - i + 1)
        return max_len

