class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        from collections import deque

        n = len(nums)
        start = tuple(nums)
        if all(x == 0 for x in start):
            return 0

        visited = set()
        visited.add(start)
        queue = deque()
        queue.append((start, 0))

        while queue:
            state, k = queue.popleft()
            if k >= len(queries):
                continue
            l, r, val = queries[k]
            length = r - l + 1
            # Generate all subsets of the range [l, r]
            for mask in range(1 << length):
                new_state = list(state)
                for i in range(length):
                    if mask & (1 << i):
                        idx = l + i
                        new_state[idx] -= val
                new_state_tuple = tuple(new_state)
                if all(x == 0 for x in new_state_tuple):
                    return k + 1
                if new_state_tuple not in visited:
                    visited.add(new_state_tuple)
                    queue.append((new_state_tuple, k + 1))
        return -1

