                    adj[i].append(j)
                    adj[j].append(i)

        visited = [False] * n
        def dfs(u: int):
            stack = [u]
            visited[u] = True
            while stack:
                node = stack.pop()
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
