class BIT:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, x):
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

    def find_kth(self, k):
        i = 0
        bit_mask = 1 << (self.n.bit_length() - 1)
        while bit_mask:
            t = i + bit_mask
            if t <= self.n and self.bit[t] < k:
                i = t
                k -= self.bit[t]
            bit_mask >>= 1
        return i + 1

